-- 966: Кекур «Чёртов палец» — новое место и снимок владельца.
--
-- В каталоге такого места НЕ БЫЛО: перепись по «палец» по всем миграциям дала
-- ноль совпадений в любом написании. Заводится запись, а не прикладывается
-- фото.
--
-- ── Координата ────────────────────────────────────────────────────────────
--
-- 52.9116357, 158.6794059 — прислана владельцем со ссылкой на картографические
-- источники (Яндекс.Карты, autotravel). coord_source = 'external': взята из
-- внешнего справочника, не снята прибором и не угадана по имени. Значение
-- заведено в перечень миграцией 960 — до неё такие координаты записывались
-- своим словом и рендерились в поле как «Координата точки: undefined».
--
-- Точка проверена по смыслу, а не только конвертом края: 52.91/158.68 — это
-- восточный берег Авачинской губы, бухта Большая Лагерная, и снимок владельца
-- это подтверждает — кекуры у воды в отлив, вулкан за губой.
--
-- ── Что в описании и чего в нём нет ───────────────────────────────────────
--
-- Сказано то, что прислал владелец: высота около 25,5 м, расположение,
-- птицы и нерпы, подход в отлив. Народное имя «Каменная стрела Перуна» дано
-- как народное, а не как второе официальное.
--
-- НЕ написано, из какой породы кекур, когда отделился от берега и почему так
-- назван: всё это находится правдоподобным, а проверить отсюда нечем.
--
-- ── Предупреждение про отлив — не украшение ───────────────────────────────
--
-- «В отлив можно подойти близко» на карточке безопасности обязано нести и
-- вторую половину: прилив отрезает. Написано прямо, потому что человек
-- пойдёт именно по этой фразе.
--
-- Идемпотентно: место — по WHERE NOT EXISTS на имя, снимок — ON CONFLICT по
-- route_id с защитой существующего ручного снимка.

INSERT INTO places
  (id, ark_id, name, description, lat, lng, location_type, category,
   source_url, source_name, coord_source, coord_source_at, is_visible)
SELECT
  'ef504046-2c40-438a-ad75-bb59fca5a52f',
  'ef504046-2c40-438a-ad75-bb59fca5a52f'::uuid,
  'Кекур Чёртов палец',
  'Кекур «Чёртов палец» — отдельно стоящая скала-останец у восточного берега Авачинской губы, в бухте Большая Лагерная Елизовского района, примерно в двадцати километрах от центра Петропавловска-Камчатского. Высота над водой около 25,5 метра. В народе скалу иногда называют «Каменной стрелой» Перуна.

Вокруг кекура держится птица, в воде у основания встречаются нерпы. В отлив к скале можно подойти по обнажившемуся дну почти вплотную — и в этом же весь риск: прилив возвращается и отрезает путь обратно. Время воды здесь проверяют до выхода, а не на месте.',
  52.9116357, 158.6794059,
  'rock', 'rock',
  'https://yandex.ru/maps/',
  'координата от владельца по картографическим источникам + его снимок',
  'external',
  NOW(),
  TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM places WHERE name ILIKE '%чертов палец%' OR name ILIKE '%чёртов палец%'
);

